function renderFields(node: JsonSchemaNode, depth: number): string[] {
  const required = new Set(node.required ?? []);
  return Object.entries(node.properties ?? {}).map(([key, value]) => {
    const rendered = renderSchemaType(value, depth);
    return `${key}${required.has(key) ? '' : '?'}: ${rendered}`;
  });
}

export function renderSchemaType(node: JsonSchemaNode | undefined, depth = 0): string {
  if (!node) return 'unknown';
  if (node.const !== undefined) return JSON.stringify(node.const);
  if (node.enum?.length) {
    const rendered = node.enum.map((value) => JSON.stringify(value)).join('|');
    if (rendered.length <= SHORT_ENUM_MAX_CHARS) return rendered;
    // A long union (e.g. the skill catalogue) would drown the signature; the
    // real schema (and any zod failure issue) still names every value.
    return node.enum.every((value) => typeof value === 'number') ? 'number' : 'string';
  }
  const union = node.anyOf ?? node.oneOf;
  if (union?.length) {
    const parts = [...new Set(union.map((member) => renderSchemaType(member, depth)))].filter(
      (part) => part !== 'unknown',
    );
    return parts.length === 0 ? 'unknown' : parts.join('|');
  }
  const type = Array.isArray(node.type) ? node.type.filter((entry) => entry !== 'null')[0] : node.type;
  switch (type) {
    case 'string':
    case 'boolean':
    case 'null':
      return type;
    case 'number':
    case 'integer':
      return 'number';
    case 'array':
      return `${renderSchemaType(Array.isArray(node.items) ? node.items[0] : node.items, depth)}[]`;
    case 'object':
    default:
      return node.properties && depth < MAX_OBJECT_DEPTH ? `{ ${renderFields(node, depth + 1).join(', ')} }` : 'object';
  }
}

function schemaFor(parameters: unknown, io: 'input' | 'output' = 'input'): JsonSchemaNode | null {
  if (isZodToolParameterSchema(parameters)) {
    try {
      return z.toJSONSchema(parameters, { io }) as JsonSchemaNode;
    } catch {
      return null;
    }
  }
  if (parameters && typeof parameters === 'object') {
    return parameters as JsonSchemaNode;
  }
  return null;
}

function scriptedReturnDescription(tool: ToolRegistry[number]): { value: string; legacy?: string } {
  const contract = getScriptedReturnContract(tool);
  if (contract.kind === 'unknown') {
    return {
      value: 'unknown',
      ...(typeof tool.scriptedReturnShape === 'string' && tool.scriptedReturnShape
        ? { legacy: tool.scriptedReturnShape }
        : {}),
    };
  }
  const schema = schemaFor(contract.schema, 'output');
  return {
    value: schema ? renderSchemaType(schema) : 'unknown',
    ...(typeof tool.scriptedReturnShape === 'string' && tool.scriptedReturnShape
      ? { legacy: tool.scriptedReturnShape }
      : {}),
  };
}

const oneLine = (text: string): string => {
  const collapsed = text.replace(/\s+/g, ' ').trim();
  return collapsed.length <= MAX_DESCRIPTION_CHARS
    ? collapsed
    : `${collapsed.slice(0, MAX_DESCRIPTION_CHARS).trimEnd()}…`;
};

/**
 * The call shape for one tool — `tools.name({ field: type, ... })` — with short
 * enums inlined, nested object shapes expanded, and long enums degraded.
 * Shared by the header and the invalid-parameters failure message, so the two
 * never drift apart.
 */
export function renderCompactSignature(tool: {
  name: string;
  parameters: unknown;
  canonicalParameters?: unknown;
}): string {
  const targetSchema = tool.canonicalParameters ?? tool.parameters;
  const schema = schemaFor(targetSchema);
  if (
    !schema ||
    schema.anyOf !== undefined ||
    schema.oneOf !== undefined ||
    schema.properties === undefined ||
    (schema.type !== undefined &&
      schema.type !== 'object' &&
      (!Array.isArray(schema.type) || !schema.type.includes('object')))
  ) {
    return `tools.${tool.name}(/* schema unavailable — use tools.describe */)`;
  }
  const fields = renderFields(schema, 0);
  return `tools.${tool.name}({ ${fields.join(', ')} })`.replace('({  })', '()');
}

/** The header bullet for a fully rendered tool: signature plus one-line description and declared return shape. */
export function renderDetailedEntry(tool: ToolRegistry[number]): string {
  const description = typeof tool.description === 'string' && tool.description ? ` — ${oneLine(tool.description)}` : '';
  const scriptedReturn = scriptedReturnDescription(tool);
  const returns = `\n    returns ${scriptedReturn.value}${
    scriptedReturn.legacy ? ` (guidance: ${scriptedReturn.legacy})` : ''
  }`;
  return `- ${renderCompactSignature(tool)}${description}${returns}`;
}

function renderCompactEntry(tool: ToolRegistry[number]): string {
  // Mirror renderDetailedEntry: surface the declared return shape as guidance
  // even when no scriptedReturnSchema makes the contract precise, so a script
  // sees the actual result shape instead of a bare 'returns unknown'.
  const scriptedReturn = scriptedReturnDescription(tool);
  const returns = ` — returns ${scriptedReturn.value}`;
  const guidance = scriptedReturn.legacy ? ` (guidance: ${scriptedReturn.legacy})` : '';
  return `- ${renderCompactSignature(tool)}${returns}${guidance}`;
}

/**
 * Renders the catalogue of `tools.*` members a script can call.
 *
 * Parameter signatures are approximate structural renderings. Script return
 * types, when present, are rendered from the owner schema; missing contracts
 * are explicitly shown as unknown rather than inferred from prose, with any
 * declared prose shape surfaced alongside as guidance.
 */
export function renderToolsHeader(registry: ToolRegistry): string {
  if (registry.length === 0) return '';
  const essential = registry.filter((tool) => RUN_CODE_ESSENTIAL_TOOLS.has(tool.name));
  const other = registry.filter((tool) => !RUN_CODE_ESSENTIAL_TOOLS.has(tool.name));
  const lines = [
    'Available inside the script (parameter shapes are approximate; each call is validated against the tool’s real schema):',
    'Use tools.describe(name) when you need the full schema and description for a tool.',
    'Use only the tools listed here: a name that is not listed is not available inside the script.',
    ...(essential.length > 0 ? ['Essential tools:', ...essential.map(renderDetailedEntry)] : []),
    ...(other.length > 0
      ? [...(essential.length > 0 ? [''] : []), 'Other tools:', ...other.map(renderCompactEntry)]
      : []),
  ];
  return lines.join('\n');
}
